---level17 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl17_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		sound.play("43-1")		if dialog.show("Level17-1", faceWeixiao) ==1 then break end		if dialog.show("Level17-2", faceWeixiao) ==1 then break end				--set story viewed flag        global.setBool("lvl17_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false	until trueendif isSkip then	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end